package com.shrija.recruitment.controller; import com.shrija.recruitment.dto.*; import com.shrija.recruitment.service.RecruitmentConversationService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/recruitment") public class RecruitmentController { private final RecruitmentConversationService service; public RecruitmentController(RecruitmentConversationService service){this.service=service;} @PostMapping("/chat") public ResponseEntity<RecruitmentChatResponse> chat(@Valid @RequestBody RecruitmentChatRequest r){var x=service.converse(r);return ResponseEntity.ok(new RecruitmentChatResponse(x.sessionId(),x.responseText()));} }
